api.look('agent');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 1.6);
api.path('M0 -150 C50 -90 55 0 40 70 L-40 70 C-55 0 -50 -90 0 -150 Z', {x:cx, y:cy, s:1.3, c:'fg', w:4, fill:'panel', k});
api.circle(cx, cy-40, 26*k, {c:'a2', w:4, fill:'ink'});
api.path('M-40 40 L-85 105 L-40 85 Z', {x:cx, y:cy, s:1.3, c:'accent', w:4, fill:'accent', k:api.seg(t,0.6,1.6)});
api.path('M40 40 L85 105 L40 85 Z', {x:cx, y:cy, s:1.3, c:'accent', w:4, fill:'accent', k:api.seg(t,0.6,1.6)});
api.swarm(30, t, {mode:'fall', cx:cx, cy:cy+130, rx:30, ry:90, c:'accent', glow:true});
api.kinetic('Launch Friday', cx, 640, {mode:'rise', k:api.seg(t,1.2,2.6), size:40, t});
api.say('Launch is Friday', 0.3, 3.5);

api.look('agent');
const cx = api.w/2;
const gx = 45, gy = 190, cw = 60, gap = 10;
api.text('20 tasks', cx, 110, {size:40, weight:700, align:'center', k:api.seg(t,0,0.8)});
for (let i = 0; i < 20; i++) {
  const col = i % 5, row = Math.floor(i / 5);
  const x = gx + col*(cw+gap)+cw/2, y = gy + row*(cw+gap+14)+cw/2;
  const kk = api.stag(t, i, {gap:0.08, dur:0.4, from:0.4});
  const done = i < 14;
  const blocked = i >= 14 && i < 17;
  const colr = done ? 'good' : blocked ? 'warn' : 'dim';
  api.box(x, y, cw*kk, cw*kk, {c:colr, w:3, fill: done ? 'good' : 'panel', a:1});
  if (done) api.shape('check', x, y, 30*kk, {c:'ink', w:4});
  else if (blocked) api.shape('lock', x, y, 30*kk, {c:'warn', w:3});
}
api.counter(14, cx, 590, {k:api.seg(t,2.5,4.5), suf:' done', size:44, c:'good'});
api.brace(gx, gy+cw*3+gap*3+60, gx+5*cw+4*gap, gy+cw*3+gap*3+60, {k:api.seg(t,3.5,4.5)});
api.say('Fourteen are done', 2.5, 5.5);

api.look('agent');
const cx = api.w/2;
const zoom = api.lerp(1, 1.15, api.ease(api.seg(t,0,2)));
api.focus(cx, 360, zoom);
api.text('Blocked', cx, 130, {size:40, weight:700, align:'center', c:'warn', k:api.seg(t,0,0.8)});
const a = api.node(cx-110, 330, 140, 90, 'Review', {icon:'doc', k:api.seg(t,0.4,1.2), c:'a3'});
for (let i = 0; i < 3; i++) {
  const x = cx + 90 + (i%2)*0, y = 260 + i*80;
  const kk = api.stag(t, i, {gap:0.3, dur:0.5, from:1});
  api.box(x+40, y, 130*kk, 56*kk, {c:'warn', w:3, fill:'panel'});
  api.shape('lock', x+40, y, 28*kk, {c:'warn', w:3});
  api.link(a, {x:x-25, y:y, l:x-25, r:x-25, t:y, b:y}, {k:kk, c:'warn', flow:t});
}
api.counter(3, cx, 600, {k:api.seg(t,2,3.5), suf:' blocked', size:44, c:'warn'});
api.say('Three wait on App Review', 1.5, 5.5);

api.look('agent');
const cx = api.w/2;
api.text('Not started', cx, 130, {size:40, weight:700, align:'center', c:'dim', k:api.seg(t,0,0.8)});
for (let i = 0; i < 3; i++) {
  const kk = api.stag(t, i, {gap:0.35, dur:0.6, from:0.5});
  const y = 270 + i*110;
  api.box(cx, y, 280*kk, 80*kk, {c:'dim', w:3, dash:[6,6], fill:'panel'});
  api.shape('cup', cx-90, y, 36*kk, {c:'dim', w:3});
}
api.counter(3, cx, 640, {k:api.seg(t,1.8,3.2), suf:' to start', size:44, c:'dim'});
api.say('Three have not started', 1, 4.5);

api.look('agent');
const cx = api.w/2;
const x = 35, w = api.w-70, y = 330, h = 70;
const total = 20, cwid = w/total;
api.text('Where we are', cx, 150, {size:36, weight:700, align:'center', k:api.seg(t,0,0.8)});
const segs = [[0,14,'good'],[14,17,'warn'],[17,20,'dim']];
segs.forEach((s,i) => {
  const kk = api.seg(t, 0.5+i*0.9, 1.4+i*0.9);
  const sx = x + s[0]*cwid, sw = (s[1]-s[0])*cwid*kk;
  api.rect(sx, y, sw, h, {c:s[2], fill:s[2], w:3});
});
api.label('14 done', x+7*cwid, y+h+40, {k:api.seg(t,1.4,2.2)});
api.label('3 blocked', x+15.5*cwid, y-40, {k:api.seg(t,2.3,3.1)});
api.label('3 to go', x+18.5*cwid, y+h+40, {k:api.seg(t,3.2,4)});
const fx = x + 17*cwid;
api.arrow(fx, y+h+110, fx, y+h+10, {k:api.seg(t,4,5), c:'accent'});
api.say('Review is the gate', 3.8, 5.8);

api.look('agent');
const cx = api.w/2, cy = 360;
const k = api.seg(t, 0, 1.5);
api.donut([{v:14,c:'good'},{v:3,c:'warn'},{v:3,c:'dim'}], cx, cy, 130, {k});
api.counter(70, cx, cy+14, {k:api.seg(t,0,1.8), suf:'%', size:56});
api.kinetic('Friday', cx, 620, {mode:'pop', k:api.seg(t,1.5,2.8), size:44, hot:true, t});
api.glow(cx, cy, 190+api.pulse(t,1)*20, {c:'accent'});
api.say('Unblock review, then ship', 1.2, 4.8);
